-- BA-159: one row per image generated with Photoroom. The file itself is in the "generated-images" Storage bucket.
-- Only the app's server reads and writes this table (through DATABASE_URL), and it always filters on the organization's own store.

CREATE TABLE "public"."generated_image" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "store_id"           bigint                   NOT NULL,
  -- Full Shopify ID, e.g. "gid://shopify/Product/8123456789". Needed as-is to upload the image to Shopify later.
  "shopify_product_id" text                     NOT NULL,
  -- Image type from src/lib/image-types.ts. Validated in the app, so a new type does not need a migration.
  "type"               text                     NOT NULL,
  -- The Shopify image it was generated from. Both become nullable when uploading from a computer is added.
  "source_image_id"    text                     NOT NULL,
  "source_image_url"   text                     NOT NULL,
  -- Path inside the bucket: "{store_id}/{product number}/{uuid}.{ext}".
  "storage_path"       text                     NOT NULL,
  "status"             text                     NOT NULL DEFAULT 'draft',

  CONSTRAINT "generated_image_pkey" PRIMARY KEY ("id"),
  -- Deleting a store deletes its rows. Its files in Storage are not deleted automatically.
  CONSTRAINT "generated_image_store_id_fkey" FOREIGN KEY ("store_id") REFERENCES "public"."store" ("id") ON DELETE CASCADE,
  CONSTRAINT "generated_image_storage_path_key" UNIQUE ("storage_path"),
  CONSTRAINT "generated_image_status_check" CHECK ("status" IN ('draft', 'approved', 'rejected'))
);

-- The product page looks up all images for one product in one store.
CREATE INDEX "generated_image_store_id_shopify_product_id_idx"
  ON "public"."generated_image" ("store_id", "shopify_product_id");

-- RLS on with no policies, and no access for the public API roles: only the server (postgres role) can use the table.
ALTER TABLE "public"."generated_image"
  ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."generated_image" FROM "anon", "authenticated";
REVOKE ALL ON SEQUENCE "public"."generated_image_id_seq" FROM "anon", "authenticated";
